/**
 * Public-build guard: no DBXV2 module, type declaration or marker may reach a public bundle or
 * release tree. Every module generated by the `dbxv2:` plugin carries {@link DBXV2_MARKER}, and
 * the public server build (`scripts/build/server.ts`) fails when it finds one.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { Dbxv2BuildRefusedError } from "./errors";
import { isPublicContext, type Dbxv2EnvInput } from "./env";

/** Literal present in every generated module and declaration file. */
export const DBXV2_MARKER = "@dbxv2-private";

/** Basename of the generated declarations. */
export const DBXV2_DECLARATIONS_FILE = "dbxv2.d.ts";

/** The subset of `Bun.build` options the guard looks at. */
export interface BuildConfigLike {
  readonly minify?: unknown;
  readonly define?: Readonly<Record<string, string>>;
  readonly sourcemap?: unknown;
  readonly splitting?: unknown;
}

/** Why a build is considered public/production, or null when it is a development build. */
export function publicBuildReason(
  config: BuildConfigLike | undefined,
  env: Dbxv2EnvInput,
): string | null {
  const context = isPublicContext(env);
  if (context === "public-render") return "SHENRON_PROFILE/SHENRON_PUBLIC_* marks a public build";
  if (context === "production") return "NODE_ENV=production";
  if (config?.minify) return "minify is enabled (production build)";
  const nodeEnv = config?.define?.["process.env.NODE_ENV"];
  if (nodeEnv !== undefined && /production/.test(nodeEnv)) return "define NODE_ENV=production";
  return null;
}

/** Throws {@link Dbxv2BuildRefusedError} when a public or production build asks for DBXV2 modules. */
export function assertDbxv2BuildAllowed(
  config: BuildConfigLike | undefined,
  env: Dbxv2EnvInput,
): void {
  const reason = publicBuildReason(config, env);
  if (reason) {
    throw new Dbxv2BuildRefusedError(
      `Bun.build refused for dbxv2: modules (${reason}). DBXV2 is private (Bandai Namco / Dimps) ` +
        "and must never be bundled into a public or production artifact.",
    );
  }
}

const SCANNED = /\.(?:m?js|cjs|ts|mts|cts|d\.ts|map|json|html)$/i;
const MAX_FILE = 16 * 1024 * 1024;

/**
 * Files under `dir` that carry the DBXV2 marker or are the generated declarations (paths relative
 * to `dir`). `node_modules` are not skipped: a leak there ships as well.
 */
export function findDbxv2Leaks(dir: string): string[] {
  const leaks: string[] = [];
  const walk = (current: string, prefix: string): void => {
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
      const full = join(current, entry.name);
      if (entry.isDirectory()) {
        walk(full, rel);
        continue;
      }
      if (!entry.isFile()) continue;
      if (entry.name === DBXV2_DECLARATIONS_FILE) {
        leaks.push(rel);
        continue;
      }
      if (!SCANNED.test(entry.name)) continue;
      let size: number;
      try {
        size = statSync(full).size;
      } catch {
        continue;
      }
      if (size > MAX_FILE) continue;
      if (readFileSync(full, "latin1").includes(DBXV2_MARKER)) leaks.push(rel);
    }
  };
  walk(dir, "");
  return leaks;
}
